// Legacy URL → new URL map for the trukafrik.com migration.
//
// Source of truth for next.config.ts redirects() and for docs/redirects/301-map.csv
// (generated by `node scripts/redirect-map.ts`).
//
// Rules:
// - `source` is the old (Duda) path, no trailing slash. The old site answered
//   https://www.trukafrik.com + path; host/http canonicalisation is handled by the host.
// - `destination` may carry a fragment (`/#the-range`) when the new one-page home
//   owns the equivalent content.
// - `equivalence` records how well the destination covers the old page:
//     exact     the same page exists on the new site
//     section   the closest matching section of the new home page
//     lost      no equivalent content exists yet (redirect to / costs the page's SEO equity)
//     retired   content deliberately dropped; redirect kept only to avoid dead links

export type RedirectEquivalence = 'exact' | 'section' | 'lost' | 'retired';

export type LegacyRedirect = {
  source: string;
  destination: string;
  oldTitle: string;
  category: string;
  equivalence: RedirectEquivalence;
  note: string;
};

